function whatsappUrl(international?: string, fallback?: string) { const source = international || fallback || ""; let digits = source.replace(/\D/g, ""); if (/^00/.test(source)) digits = digits.replace(/^00/, ""); else if (!international && !source.trim().startsWith("+")) return undefined; return digits.length >= 8 ? `https://wa.me/${digits}` : undefined; }
